css:
.sb-annual col.sb-line,
.sb-annual col.sb-kz {
	width: 10mm;
}

.sb-annual .sb-line {
	color: #555;
}

.sb-annual .sb-kz {
	text-align: center;
}

.sb-annual .sb-columns td {
	color: #555;
	font-size: 8pt;
}

.sb-annual .sb-subheading td {
	color: #444;
	font-style: italic;
}

.sb-annual .sb-text {
	text-align: left;
}

.sb-annual .sb-wide {
	font-size: 7.5pt;
	table-layout: auto;
}

.sb-annual .sb-wide .sb-num {
	width: auto;
}
